public IList<IList<int>> Subsets(int[] nums)
{
    var result = new List<IList<int>>();
    Build(nums, 0, new List<int>(), result);
    return result;
}

private void Build(int[] nums, int i, List<int> current, List<IList<int>> result)
{
    if (i == nums.Length) { result.Add(new List<int>(current)); return; }
    current.Add(nums[i]);               // include nums[i]
    Build(nums, i + 1, current, result);
    current.RemoveAt(current.Count - 1); // exclude nums[i] (backtrack)
    Build(nums, i + 1, current, result);
}

public IList<IList<int>> Subsets(int[] nums)
{
    var result = new List<IList<int>>();
    var current = new List<int>();
    void Dfs(int start)
    {
        result.Add(new List<int>(current));    // every state is a valid subset
        for (int i = start; i < nums.Length; i++)
        {
            current.Add(nums[i]);              // choose
            Dfs(i + 1);                        // explore
            current.RemoveAt(current.Count - 1); // un-choose (backtrack)
        }
    }
    Dfs(0);
    return result;
}
